"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["94496"],{16543(e){e.exports=JSON.parse('{"id":"FIN-1091","slug":"normalized-earnings","term":"Normalized Earnings","also_known_as":[],"difficulty":"Advanced","definition":"Normalized earnings are a company\'s profits adjusted to remove unusual, one-time or non-recurring items, and sometimes to smooth out the effects of the business cycle, to show what the business earns in a typical year.","explanation":["Reported profits can be distorted by events that are unlikely to repeat, such as gains from selling assets, restructuring costs, legal settlements, impairments or unusual weather. Normalizing removes these items to reveal underlying performance.","For example, a company reports net income of 8,000,000, including a one-off gain of 3,000,000 from selling a property. Its normalized earnings, excluding the gain, are about 5,000,000 before considering any tax effect.","For cyclical businesses, normalized earnings may also be estimated as average earnings over a full economic cycle, since a single year at a peak or trough can be misleading.","Normalized earnings are useful for valuation, since valuing a company on unusually high or low profits can give a distorted result. But normalization involves judgment. Companies sometimes label recurring costs as one-time to present a more favourable picture, so analysts should examine the adjustments carefully."],"note":"","total":1725,"prev":{"slug":"normal-good","term":"Normal Good"},"next":{"slug":"notes-to-financial-statements","term":"Notes to Financial Statements"}}')}}]);